import android.content.SharedPreferences;
import com.androidhit.lumadrift.data.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Real store APIs: retire new Shield offers without deleting old ownership or exact retries. */
public final class PowerOffersV114Test {
    static int checks;
    static void check(boolean ok,String detail){checks++;if(!ok)throw new AssertionError(detail);}
    static RewardsCosmeticsV17Test.Ctx context(){return new RewardsCosmeticsV17Test.Ctx();}
    static GameStore store(RewardsCosmeticsV17Test.Ctx c){return new GameStore(c);}
    static GameStore progress(RewardsCosmeticsV17Test.Ctx c,int clears){GameStore s=store(c);for(int n=1;n<=clears;n++)s.completeLevel(n,3);return s;}
    static void saveFailure(Runnable action,String detail){try{action.run();throw new AssertionError("Expected local-save refusal: "+detail);}catch(GameStore.LocalSaveException expected){checks++;}}
    static String hash(String value)throws Exception{byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:digest)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
    static void oldTrackedDecision(SharedPreferences prefs,Map<String,Object> values){try{Class<?> type=Class.forName("com.androidhit.lumadrift.data.LocalSaveTransactions");Method write=type.getDeclaredMethod("write",SharedPreferences.class,Map.class);write.setAccessible(true);write.invoke(null,prefs,values);}catch(InvocationTargetException error){if(error.getCause() instanceof GameStore.LocalSaveException)throw(GameStore.LocalSaveException)error.getCause();throw new AssertionError(error.getCause());}catch(ReflectiveOperationException error){throw new AssertionError(error);}}
    @SuppressWarnings("unchecked") static void oldLootDecision(SharedPreferences prefs,int milestone,String item){try{Class<?> type=Class.forName("com.androidhit.lumadrift.data.GameStore$LootRetry");Constructor<?> ctor=type.getDeclaredConstructor(int.class,String.class);ctor.setAccessible(true);Field field=GameStore.class.getDeclaredField("LOOT_RETRIES");field.setAccessible(true);((Map<SharedPreferences,Object>)field.get(null)).put(prefs,ctor.newInstance(milestone,item));}catch(ReflectiveOperationException error){throw new AssertionError(error);}}
    static void offers(){check(Catalog.BOOSTERS.length==6&&Catalog.booster("shield")!=null,"Legacy Shield definition remains addressable");int offered=0;for(Catalog.BoosterItem item:Catalog.BOOSTERS){boolean available=Catalog.isPowerOffered(item.id);check(available==!item.id.equals("shield"),"Exactly the retired power is excluded");if(available)offered++;}check(offered==5&&!Catalog.isPowerOffered(null)&&!Catalog.isPowerOffered("missing"),"Five current powers, unknown IDs cannot become offers");
        RewardsCosmeticsV17Test.Ctx c=context();GameStore s=progress(c,75);c.save().edit().putInt("booster_shield",7).commit();Map<String,?> before=c.save().getAll();check(!s.powerTrialAvailable("shield")&&!s.powerTrialClaimed("shield"),"Retired unclaimed trial is never offered");check(s.claimPowerTrial("shield")==GameStore.PowerTrialStatus.NOT_OFFERED,"Retired trial refused explicitly");check(!s.purchaseBooster("shield")&&s.boosterStock("shield")==7,"New Shield purchase refused while old stock survives");check(c.save().getAll().equals(before),"Offer reads and new refusals do not mutate save or coins");
        List<InventoryPresentation.Power> powers=InventoryPresentation.powers(s,Set.of("shield"));check(powers.size()==5&&powers.stream().noneMatch(p->p.id.equals("shield")),"Current inventory offers omit retired power");check(InventoryPresentation.nextPower(12).id.equals("focus")&&InventoryPresentation.nextPower(24).id.equals("focus"),"Next offer skips obsolete Shield milestone");
        MetaProgress meta=new MetaProgress(c);ObjectiveDashboard.Snapshot dash=ObjectiveDashboard.snapshot(s,meta);check(dash.trials.size()==5&&dash.trialsReadyCount==5&&!dash.readyTrialIds.contains("shield"),"Home/reward dashboard contains only five useful trial offers");check(dash.trials.stream().noneMatch(t->t.id.equals("shield")),"Retired trial absent even as a locked future advertisement");
        for(Catalog.BoosterItem item:Catalog.BOOSTERS)if(Catalog.isPowerOffered(item.id)){int stock=s.boosterStock(item.id),coins=s.coins();check(s.claimPowerTrial(item.id)==GameStore.PowerTrialStatus.GRANTED&&s.boosterStock(item.id)==stock+1&&s.coins()==coins,"Useful free sample still grants exact charge "+item.id);int price=s.boosterPrice(item.id);check(s.purchaseBooster(item.id)&&s.coins()==coins-price&&s.boosterStock(item.id)==stock+1+item.amount,"Useful pack still debits/grants exact pair "+item.id);}
    }
    static String expected(int milestone){List<String> eligible=new ArrayList<>();for(Catalog.BoosterItem item:Catalog.BOOSTERS)if(Catalog.isPowerOffered(item.id)&&item.unlockLevel<=milestone+1)eligible.add(item.id);return eligible.get((milestone/5-1)%eligible.size());}
    static void futureGifts(){RewardsCosmeticsV17Test.Ctx a=context(),b=context();GameStore immediate=store(a),deferred=progress(b,1000);for(int n=1;n<=1000;n++){immediate.completeLevel(n,3);if(n%5!=0)continue;String id=expected(n);check(!id.equals("shield")&&immediate.nextMilestoneLootId().equals(id)&&deferred.nextMilestoneLootId().equals(id),"Stable future gift excludes Shield at "+n);int stock=immediate.boosterStock(id),later=deferred.boosterStock(id);check(immediate.claimMilestoneLoot().equals(id)&&deferred.claimMilestoneLoot().equals(id),"Immediate and deferred claims keep same offered item at "+n);check(immediate.boosterStock(id)==stock+1&&deferred.boosterStock(id)==later+1,"One exact unit per future gift");check(immediate.claimMilestoneLoot().isEmpty(),"Repeated future gift cannot duplicate");}check(immediate.nextLootMilestone()==0&&deferred.nextLootMilestone()==0,"All200 gifts terminate");check(immediate.boosterStock("shield")==0&&deferred.boosterStock("shield")==0,"No hidden retired stock granted by future gifts");}
    static void archive()throws Exception{RewardsCosmeticsV17Test.Ctx c=context();GameStore s=progress(c,75);c.save().edit().putString("power_loot_v1_5","shield").putString("power_loot_v19_10","shield").putBoolean("power_trial_v19_shield",true).putInt("booster_shield",7).putString("booster_reward_v1_"+hash("old:shield:reward"),"shield").commit();Map<String,?> before=c.save().getAll();GameStore cold=store(c.reboot());check(cold.boosterStock("shield")==7&&cold.powerTrialClaimed("shield"),"Historical stock and trial receipt survive cold recreation");check(cold.claimPowerTrial("shield")==GameStore.PowerTrialStatus.ALREADY_CLAIMED,"Historical claimed trial stays acknowledged");check(cold.nextLootMilestone()==15,"Both old receipt namespaces remain claimed");check(cold.hasBoosterGranted("shield","old:shield:reward")&&cold.grantBoosterOnce("shield","old:shield:reward")==0,"Old idempotent ad/gift receipt remains acknowledged without another grant");check(c.save().getAll().equals(before),"Observing cold archive never rewrites original prefs");
        check(s.reserveBoosterUse("shield","old:shield:effect"),"Legacy effect reservation remains addressable");check(s.boosterStock("shield")==6&&s.pendingBoosterUse().id.equals("shield"),"Escrow remains exact without deleting physical stock");GameStore resumed=store(c.reboot());check(resumed.pendingBoosterUse()!=null&&resumed.cancelBoosterUse("shield","old:shield:effect")&&resumed.boosterStock("shield")==7,"Old reservation can be cancelled after process restart, without lost stock");check(resumed.reserveBoosterUse("shield","old:shield:effect2")&&resumed.completeBoosterUse("shield","old:shield:effect2")&&resumed.boosterStock("shield")==6,"Already-authorized legacy effect can settle once");check(resumed.completeBoosterUse("shield","old:shield:effect2")&&resumed.boosterStock("shield")==6,"Completion receipt remains idempotent");}
    static void pendingTracked(){for(boolean memory:new boolean[]{false,true}){RewardsCosmeticsV17Test.Ctx c=context();GameStore s=progress(c,75);int stock=s.boosterStock("shield");Map<String,Object> trial=new HashMap<>();trial.put("power_trial_v19_shield",true);trial.put("booster_shield",stock+1);c.save().fail(memory);saveFailure(()->oldTrackedDecision(c.save(),trial),"old trial decision "+memory);check(!c.save().disk.containsKey("power_trial_v19_shield"),"Failed old trial has no partial disk receipt");check(s.claimPowerTrial("shield")==GameStore.PowerTrialStatus.ALREADY_CLAIMED&&s.boosterStock("shield")==stock+1,"Retirement flushes exact earlier sample once");check(store(c.reboot()).boosterStock("shield")==stock+1,"Earlier sample is durably preserved");
            RewardsCosmeticsV17Test.Ctx p=context();GameStore buyer=progress(p,75);int coins=buyer.coins(),old=buyer.boosterStock("shield"),price=buyer.boosterPrice("shield");Map<String,Object> purchase=new HashMap<>();purchase.put("coins",coins-price);purchase.put("booster_shield",old+Catalog.booster("shield").amount);p.save().fail(memory);saveFailure(()->oldTrackedDecision(p.save(),purchase),"old purchase decision "+memory);check(!buyer.purchaseBooster("shield"),"New offer refused after settling old exact purchase");check(buyer.coins()==coins-price&&buyer.boosterStock("shield")==old+Catalog.booster("shield").amount,"One prior debit and grant survive retirement");buyer.retryPendingLocalSave();check(!buyer.purchaseBooster("shield")&&buyer.coins()==coins-price,"Repeated refusal cannot buy or charge again");check(store(p.reboot()).coins()==coins-price,"Old purchase persists across cold recreation");}}
    static void pendingLoot(){for(boolean memory:new boolean[]{false,true}){RewardsCosmeticsV17Test.Ctx c=context();GameStore s=progress(c,40);for(int n=5;n<40;n+=5)c.save().edit().putString("power_loot_v19_"+n,"hint").commit();int stock=s.boosterStock("shield");oldLootDecision(c.save(),40,"shield");c.save().fail(memory);check(!c.save().edit().putString("power_loot_v19_40","shield").putInt("booster_shield",stock+1).commit(),"Real prefs failure for previously selected Shield loot");check(s.nextLootMilestone()==40&&s.nextMilestoneLootId().equals("shield"),"Existing selected loot keeps original item, despite new offer policy");check(s.claimMilestoneLoot().equals("shield")&&s.boosterStock("shield")==stock+1,"Retry persists exact old loot item without substitution");check(s.nextLootMilestone()==45&&!s.nextMilestoneLootId().equals("shield"),"Only subsequent undecided milestone uses current offer list");check(s.claimMilestoneLoot().isEmpty()&&s.boosterStock("shield")==stock+1,"Retry acknowledgement cannot duplicate prior stock");check(store(c.reboot()).boosterStock("shield")==stock+1&&c.save().getString("power_loot_v19_40","").equals("shield"),"Original loot receipt and physical stock are durable");}}
    public static void main(String[] args)throws Exception{offers();futureGifts();archive();pendingTracked();pendingLoot();String report="{\n  \"passed\":true,\n  \"checks\":"+checks+",\n  \"currentOfferedPowers\":5,\n  \"futureMilestonesCompared\":200,\n  \"scope\":\"Actual store/presentation/dashboard APIs on JVM prefs doubles. New Shield offers refused; historical stock/receipts/escrow and exact pre-retirement decisions retained under both memory-before-disk failure models. No native or external-service acceptance.\"\n}\n";Path out=Paths.get(args.length>0?args[0]:"docs/validation/v1.14/audit-power-offers/audit-power-offers.json");Files.createDirectories(out.getParent());Files.writeString(out,report);System.out.println(report);}
}
